<table class="grid"><tr><th>Customer</th><th>Payment received from</th></tr><tr><td><strong>{{ $summary['customer'] }}</strong><br>{{ $invoice->customer?->phone }}<br>{!! nl2br(e($invoice->customer?->address ?? '')) !!}</td><td>{{ $source === 'bank' ? ($summary['plan']?->bank_name ?? 'Bank') : $summary['customer'] }}@if ($source === 'bank')<br>{{ $summary['plan']?->branch_name }}<br>Loan reference: {{ $summary['plan']?->loan_reference ?? '—' }}@endif</td></tr></table>
<table class="grid payments"><thead><tr><th>Receipt / Date</th><th>Method / Reference</th><th class="right">Amount ({{ $summary['currency'] }})</th></tr></thead><tbody>@foreach ($payments as $payment)<tr><td>RCT-{{ str_pad($payment->id, 6, '0', STR_PAD_LEFT) }}<br>{{ $payment->payment_date?->format('d M Y') }}</td><td>{{ ucwords(str_replace('_', ' ', $payment->payment_method)) }}<br>{{ $payment->transaction_id }}@if ($payment->notes)<br>{{ $payment->notes }}@endif</td><td class="right">{{ number_format($payment->amount, 2) }}</td></tr>@endforeach<tr><td colspan="2"><strong>{{ $single ? 'Payment received on this receipt' : 'Total received from ' . $source }}</strong></td><td class="right total"><strong>{{ number_format($payments->sum('amount'), 2) }}</strong></td></tr></tbody></table>
<h3>Current invoice balance — {{ $summary['currency'] }}</h3>
<table class="grid"><tr><th>Payable by</th><th class="right">Allocated share</th><th class="right">Received to date</th><th class="right">Pending from</th></tr>
