<tr><td>Invoice total</td><td colspan="3" class="right">{{ number_format($summary['total'], 2) }}</td></tr><tr><td>Total recorded receipts</td><td colspan="3" class="right">{{ number_format($summary['customer_received'] + $summary['bank_received'], 2) }}</td></tr><tr><td class="total"><strong>Total outstanding</strong></td><td colspan="3" class="right total"><strong>{{ number_format($summary['outstanding'], 2) }}</strong></td></tr></table>
